function fmt(n){return new Intl.NumberFormat("de-DE",{style:"currency",currency:"EUR"}).format(Number(n||0))}
function uid(){return Date.now().toString(36)+Math.random().toString(36).slice(2,9)}
function minsAgo(d){return Math.floor((Date.now()-new Date(d).getTime())/60000)}
function fmtTime(d){const m=minsAgo(d);return m<60?`${m}m ago`:`${Math.floor(m/60)}h ${m%60}m`}
function urgClass(d){const m=minsAgo(d);return m<10?"text-emerald-400":m<20?"text-amber-400":"text-red-400"}
